import{_ as r,o as e,c as t,a2 as l}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"猫族","description":"","frontmatter":{},"headers":[],"relativePath":"表层/种族/猫族.md","filePath":"表层/种族/猫族.md","lastUpdated":null}'),o={name:"表层/种族/猫族.md"};function i(n,a,h,s,d,u){return e(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="猫族" tabindex="-1">猫族 <a class="header-anchor" href="#猫族" aria-label="Permalink to &quot;猫族&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>猫族是神造物世界中最神秘的种族之一——<strong>目击者最多</strong>，但普通人仍旧难以见到。其外貌与已亡的虎族、豹族相近，但体型更加娇小。猫族神出鬼没，但可以肯定的是它们并非鬼怪神魔，也需要进食。</p><hr><h2 id="体貌特征" tabindex="-1">体貌特征 <a class="header-anchor" href="#体貌特征" aria-label="Permalink to &quot;体貌特征&quot;">​</a></h2><ul><li><strong>形态</strong>：与已亡的虎族、豹族外貌相近，但体型更加娇小。</li><li><strong>毛色</strong>：暂无明确记载。</li><li><strong>体型</strong>：娇小。</li></ul><hr><h2 id="种族特质" tabindex="-1">种族特质 <a class="header-anchor" href="#种族特质" aria-label="Permalink to &quot;种族特质&quot;">​</a></h2><h3 id="核心特质-神出鬼没" tabindex="-1">核心特质：神出鬼没 <a class="header-anchor" href="#核心特质-神出鬼没" aria-label="Permalink to &quot;核心特质：神出鬼没&quot;">​</a></h3><ul><li><strong>难以见到</strong>：尽管目击者最多，但普通人仍旧极难真正遇见猫族。</li><li><strong>神出鬼没</strong>：活动被目击的次数不少，但个体本身极难被追踪或锁定。</li><li><strong>需要进食</strong>：不是鬼怪神魔，是实实在在的生物，需要进食。</li></ul><h3 id="神秘的耕地" tabindex="-1">神秘的耕地 <a class="header-anchor" href="#神秘的耕地" aria-label="Permalink to &quot;神秘的耕地&quot;">​</a></h3><blockquote><p>曾经有人发现了一大片耕地，但其附近并没有任何住户，甚至连可以通行的林间小道都没有。后来经过对于足迹和耕种痕迹的判断，现已初步确定这片耕地就是猫族的耕地。</p></blockquote><blockquote><p>当然，后来也没有猫族出现来尝试收回这片耕地。</p></blockquote><p>这揭示了猫族的两个特征：</p><ul><li><strong>自给自足</strong>：猫族会耕种，具备农业生产能力。</li><li><strong>与世隔绝</strong>：耕地位于完全无住户、无道路的区域，猫族选择了极端偏远的地点维持生计；对被发现耕地也选择放弃而非出面交涉，进一步印证其回避与外族接触的生存策略。</li></ul><hr><h2 id="历史角色" tabindex="-1">历史角色 <a class="header-anchor" href="#历史角色" aria-label="Permalink to &quot;历史角色&quot;">​</a></h2><p>关于猫族在共同体时期或黑暗时代的具体参与情况，未见任何记录。猫族虽有目击记录，但其回避接触的生存策略使其在重大历史事件中未曾留下记录。详细历史沿革待后续补充。</p><hr><h2 id="当前现状" tabindex="-1">当前现状 <a class="header-anchor" href="#当前现状" aria-label="Permalink to &quot;当前现状&quot;">​</a></h2><p>猫族仍处于神出鬼没的状态。其族群规模、分布区域、社会结构均无明确记录。现有信息全部来自外界目击与推测。</p><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../历史/黑暗时代">虎族/豹族（已亡）</a></li><li><a href="./龙族">龙族</a></li></ul><hr>',25)])])}const _=r(o,[["render",i]]);export{p as __pageData,_ as default};
